phase_results.command:
docker exec -i 24860d14de30dc62f7b324ebef10b5fb-cli-1 wp --allow-root --user=1 eval '
$path = '"'"'/var/www/html/wp-content/debug.log'"'"';
$content = file_exists( $path ) ? file_get_contents( $path ) : '"'"''"'"';
$patterns = array(
	'"'"'php_notice'"'"' => '"'"'/PHP Notice|Notice:/i'"'"',
	'"'"'php_warning'"'"' => '"'"'/PHP Warning|Warning:/i'"'"',
	'"'"'php_deprecated'"'"' => '"'"'/Deprecated:/i'"'"',
	'"'"'php_fatal'"'"' => '"'"'/PHP Fatal|Fatal error/i'"'"',
	'"'"'uncaught'"'"' => '"'"'/Uncaught/i'"'"',
	'"'"'database'"'"' => '"'"'/database error|wpdb/i'"'"',
	'"'"'stack_trace'"'"' => '"'"'/Stack trace:/i'"'"',
);
$matches = array();
foreach ( $patterns as $id => $pattern ) {
	if ( preg_match_all( $pattern, (string) $content, $found ) ) {
		$matches[ $id ] = count( $found[0] );
	}
}
WP_CLI::line(
	wp_json_encode(
		array(
			'"'"'path'"'"' => $path,
			'"'"'bytes'"'"' => strlen( (string) $content ),
			'"'"'matches'"'"' => $matches,
			'"'"'ready'"'"' => empty( $matches ),
		)
	)
);
'
